// ====== CONFIG: เอา token ของ Sales Bot มาวาง ======
const TOKEN = 'SALES_TOKEN_HERE';

const body = $input.first().json.body || $input.first().json;
const events = body.events || [];
const out = [];
for (const ev of events) {
  const src = ev.source || {};
  const groupId = src.groupId || src.roomId || '';
  const userId = src.userId || '';
  const replyToken = ev.replyToken || '';
  let kind = 'none', action = '', cid = '';
  if (ev.type === 'postback') {
    kind = 'postback';
    const data = (ev.postback && ev.postback.data) || '';
    const p = {}; data.split('&').forEach(kv => { const i = kv.indexOf('='); if (i > 0) p[kv.slice(0, i)] = decodeURIComponent(kv.slice(i + 1)); });
    action = p.action || '';
    cid = p.cid || '';
  } else if (ev.type === 'join') {
    kind = 'setup';
  } else if (ev.type === 'message' && ev.message && ev.message.type === 'text') {
    const txt = (ev.message.text || '').trim().toLowerCase();
    if (txt === 'id' || txt === 'groupid' || txt === '/id' || txt === 'group id') kind = 'setup';
  }
  out.push({ json: { token: TOKEN, groupId, userId, replyToken, kind, action, cid } });
}
if (out.length === 0) return [{ json: { token: TOKEN, kind: 'none', groupId: '', userId: '', replyToken: '', action: '', cid: '' } }];
return out;

const j = $('Parse Event').item.json;
let name = 'เซล';
try { const prof = $('Get Member').item.json; if (prof && prof.displayName) name = prof.displayName; } catch (e) {}
const cur = $input.first().json || {};
const esc = (s) => String(s == null ? '' : s).replace(/'/g, "''");

const STLABEL = { new: '🔴 รอติดต่อ', following: '🟡 กำลังติดต่อ', approved: '🟢 อนุมัติแล้ว', rejected: '⚫ ไม่ผ่าน' };

let sql = 'SELECT 1;';
let reply = '';

if (j.kind === 'postback' && j.cid) {
  const code = cur.id ? ('PP-' + String(cur.id).padStart(4, '0')) : 'เคสนี้';
  const owner = (cur.assignee || '').trim();
  const status = cur.status || 'new';
  const closed = (status === 'approved' || status === 'rejected');

  if (j.action === 'claim') {
    if (owner && owner !== name) {
      reply = '⚠️ ' + code + ' มี ' + owner + ' รับไปแล้วครับ';
    } else {
      sql = `UPDATE customers SET status='following', assignee='${esc(name)}', updated_at=NOW() WHERE line_user_id='${esc(j.cid)}';`;
      reply = '📞 ' + name + ' รับ ' + code + ' แล้ว — กำลังติดต่อลูกค้า ✅';
    }
  } else if (j.action === 'approve' || j.action === 'reject') {
    if (owner && owner !== name) {
      reply = '⚠️ ' + code + ' ' + owner + ' ดูแลอยู่ — ให้เจ้าของเคสอัปเดตนะครับ';
    } else if (closed) {
      reply = 'ℹ️ ' + code + ' ปิดแล้ว: ' + (STLABEL[status] || status);
    } else {
      const ns = j.action === 'approve' ? 'approved' : 'rejected';
      sql = `UPDATE customers SET status='${ns}', assignee=COALESCE(NULLIF(assignee,''),'${esc(name)}'), updated_at=NOW() WHERE line_user_id='${esc(j.cid)}';`;
      reply = (j.action === 'approve' ? '✅ ' : '❌ ') + name + ' อัปเดต ' + code + ': ' + STLABEL[ns];
    }
  }
} else if (j.kind === 'setup') {
  reply = '🆔 Group ID ของกลุ่มนี้คือ:\n' + (j.groupId || '(ไม่พบ)') + '\n\nก๊อปไปวางใน n8n ครับ';
}

return [{ json: { sql, reply, token: j.token, replyToken: j.replyToken, groupId: j.groupId, hasReply: reply ? 'yes' : 'no' } }];
